function grid$smail(f){
	this.constructor(f);
}
grid$smail.prototype = new DirEvent();
grid$smail.prototype.afterInit = function(renderType){
	var p = this._dir;
}
grid$smail.prototype.beforeButtonGridClick = function(id){
	if (id == 'send') {
		var p = this._dir, g = p.grid(), r = p.curr("r");
		if (r == null || r < 0) return;

		var vc = g.data.val(r, 'id');   
		var ttMail = g.data.val(r, 'status');

		console.log(vc, ttMail);

		// 👉 Làm mới danh sách file theo từng phiếu
		p.options._files = []; // 🧹 Xóa sạch file cũ nếu cần
		p.request('GetData', '', [['id', 'I', vc]] , function(pp, d, run){
			if (run) {
				const listFiles = p.options._files;
				console.log(listFiles);

				const attachments = [];

				listFiles.forEach(item => {
					const param = "Download[@#]0[@#]" + item.id + "[@#]" + vc + "[@#][@#]";
					const encoded = $.encodeb64UTF8(param);
					const url = "../AppHandler/FileHandlerNoLogin.ashx?param=" + encoded;

					// 👉 Tách đuôi mở rộng từ tên file
					const filename = item.name;
					const extMatch = filename.match(/\.([a-zA-Z0-9]+)$/);
					const ext = extMatch ? extMatch[1].toLowerCase() : "";

					const mimeMap = {
						"jpg": "image/jpeg",
						"jpeg": "image/jpeg",
						"png": "image/png",
						"gif": "image/gif",
						"pdf": "application/pdf",
						"xls": "application/vnd.ms-excel",
						"xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
						"doc": "application/msword",
						"docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
						"zip": "application/zip"
					};

					attachments.push({
						path: url,
						filename: filename,
						contentType: mimeMap[ext] || "application/octet-stream"
					});
				});

				console.log(attachments);

				send(this, vc, ttMail, attachments, p);
				p._refresh();
			}
		});

		return false;
	}
	return true;
}

function send(o, id, status, attachments, pDir) {
	$.showToast(id);
	if (id == null) {
		$.showToast('Không này rỗng');
		return;
	}
	if (status !== 5) {
		$.showToast('Phiếu chưa duyệt hoặc đã hoàn thành');
		return;
	}
	popupOpen();
	var controller = 'SMail';

	var m = new Memvars();
	m.val("id", 'C', id);

	var p = window.location.href.toString();
	p = p.substring(0, p.indexOf("Main/")) + 'AppService/EService.asmx/' + "GetData";//GetValue
	$.ajax({
		type: "POST",
		url: p,
		header: '',

		data: JSON.stringify({ controller: controller, oMemvar: m.val() }),
		contentType: "application/json; charset=utf-8",
		dataType: "json",
		timeout: 30000,
		success: function (msg, s) {
			// ket qua o day
			var emailList = msg.d;
			console.log(emailList);

			let currentIndex = 0;
			let isPaused = false;
			let isCancelled = false;

			document.getElementById("totalEmails").innerText = emailList.length;
			document.getElementById("countDone").innerText = currentIndex;

			function logProgress(msg, cssClass = "") {
				const progress = document.getElementById("progressArea");
				const div = document.createElement("div");
				div.className = cssClass;
				div.textContent = msg;
				progress.appendChild(div);
				progress.scrollTop = progress.scrollHeight;
			}

			function updateProgressBar() {
				const percent = Math.floor((currentIndex / emailList.length) * 100);
				const bar = document.getElementById("progressBar");
				bar.style.width = percent + "%";
				bar.innerText = percent + "%";
			}

			function sendNextEmail() {
				if (currentIndex >= emailList.length || isCancelled) {							
					const progressBar = document.getElementById("progressBar");
					progressBar.style.backgroundColor = "#2ecc71"; // xanh lá
					progressBar.innerText = "✔ Hoàn tất!";
					logProgress("✅ Gửi xong!", "log-success");
					updateProgressBar();

					// 👉 Ẩn các nút sau khi xong
					document.getElementById("controlButtons").style.display = "none";
					return;
				}

				if (isPaused) {
					logProgress("⏸ Đang tạm dừng...", "log-paused");
					return;
				}

				const email = emailList[currentIndex];
				// ✅ Gắn mảng attachments vào email hiện tại
				email.attachments = attachments;

				fetch("/Main/SendSingleEmail.aspx", {
					method: "POST",
					headers: { "Content-Type": "application/json" },
					body: JSON.stringify(email)
				})
				.then(res => res.text())
				.then(result => {
					logProgress(`✅ (${currentIndex + 1}/${emailList.length}) ${email.r_mail} (${result})`, "log-success");
					pDir.request('Complete', '', [['id', 'I', id], ['r_mail', 'C', `${email.r_mail}`]] , function(pp, d, run){
						if (run) {
							pDir._refresh();
						}
					});
					document.getElementById("countDone").innerText = currentIndex + 1;
					currentIndex++;
					updateProgressBar();
					setTimeout(sendNextEmail, 300);
				})
				.catch(err => {
					logProgress(`❌ (${currentIndex + 1}/${emailList.length}) ${email.r_mail}: Lỗi ${err}`, "log-error");
					document.getElementById("countDone").innerText = currentIndex + 1;
					currentIndex++;
					updateProgressBar();
					setTimeout(sendNextEmail, 300);
				});
			}

			function startSending() {
				currentIndex = 0;
				isPaused = false;
				isCancelled = false;

				document.getElementById("progressArea").innerHTML = "";
				updateProgressBar();

				// 👉 Hiện các nút điều khiển khi bắt đầu gửi
				document.getElementById("controlButtons").style.display = "block";
				document.getElementById("pauseBtn").style.display = "inline-block";

				sendNextEmail();
			}

			function togglePause() {
				isPaused = !isPaused;
				const btn = document.getElementById("pauseBtn");
				btn.innerText = isPaused ? "▶️ Tiếp tục" : "⏸ Tạm dừng";

				if (!isPaused) sendNextEmail();
			}

			function cancelAll() {
				isCancelled = true;
				logProgress("❌ Đã hủy toàn bộ quá trình gửi!", "log-error");

				// 👉 Ẩn nút điều khiển sau khi hủy
				document.getElementById("pauseBtn").style.display = "none";
				document.getElementById("controlButtons").style.display = "none";
			}

			startSending();

			document.getElementById("pauseBtn").addEventListener("click", function (event) {
				togglePause(event);
			});		

			document.getElementById("cancelBtn").addEventListener("click", function () {
				cancelAll();
			});	
		},
		error: function (e) {
			// loi o day
			console.log(e);
		}
	});
}

css.text:

td.email_body {
	display: -webkit-box;
	-webkit-line-clamp: 1;       /* Hiển thị tối đa 3 dòng */
	-webkit-box-orient: vertical;
	overflow: hidden;
	max-height: 4.5em;           /* Tùy theo font-size */
}
td.email_body img, td.email_body figure {
	display: none;
}

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
	.table-bottom{
		margin-top: 42px;
		height: calc(100% - 92px);
	}
}
.toolbar-send{
	background-repeat: no-repeat;
	background-image: url('data:image/gif;base64,');
}
